// Jobs come from the first input
const jobs = $input.all();

// Build opt-out set — passed in via second input using $('Get Opt-Out List')
// n8n merges inputs; filter by sheet source via node reference
const optOutRows = $('Get Opt-Out List').all();
const optedOut = new Set(optOutRows.map(r => (r.json['Phone'] || '').trim()));

// Date range: 10–14 months ago
const now = new Date();
const tooRecent = new Date(now); tooRecent.setMonth(now.getMonth() - 10);
const tooOld    = new Date(now); tooOld.setMonth(now.getMonth() - 14);

const due = jobs.filter(row => {
  const phone = (row.json['Customer Phone'] || '').trim();
  if (!phone) return false;
  // Skip opted-out numbers
  if (optedOut.has(phone)) { console.log('Skipping opted-out:', phone); return false; }
  // Date range check
  const d = new Date(row.json['Job Date']);
  if (isNaN(d)) return false;
  return d >= tooOld && d <= tooRecent;
});

console.log('Due for reminder:', due.length, '| Opted-out skipped:', jobs.length - due.length);

return due.map(row => ({ json: {
  name:  (row.json['Customer Name']  || '').trim(),
  first: (row.json['Customer Name']  || 'there').split(' ')[0],
  phone: (row.json['Customer Phone'] || '').trim(),
  date:  row.json['Job Date']
}}));
